import java.util.Scanner;
public class HillCipher {static int inv(int a){a=Math.floorMod(a,26);for(int i=1;i<26;i++)if(a*i%26==1)return i;return -1;}public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext (letters only): ");String p=sc.nextLine().toUpperCase().replaceAll("[^A-Z]","");System.out.print("Enter key a11: ");int a=sc.nextInt();System.out.print("Enter key a12: ");int b=sc.nextInt();System.out.print("Enter key a21: ");int c=sc.nextInt();System.out.print("Enter key a22: ");int d=sc.nextInt();if(p.length()%2!=0)p+="X";int det=Math.floorMod(a*d-b*c,26),di=inv(det);if(di<0){System.out.println("Key matrix is not invertible modulo 26; decryption is impossible.");return;}StringBuilder ct=new StringBuilder(),dt=new StringBuilder();for(int i=0;i<p.length();i+=2){int x=p.charAt(i)-'A',y=p.charAt(i+1)-'A';ct.append((char)('A'+Math.floorMod(a*x+b*y,26))).append((char)('A'+Math.floorMod(c*x+d*y,26)));}int ia=Math.floorMod(d*di,26),ib=Math.floorMod(-b*di,26),ic=Math.floorMod(-c*di,26),id=Math.floorMod(a*di,26);for(int i=0;i<ct.length();i+=2){int x=ct.charAt(i)-'A',y=ct.charAt(i+1)-'A';dt.append((char)('A'+Math.floorMod(ia*x+ib*y,26))).append((char)('A'+Math.floorMod(ic*x+id*y,26)));}System.out.println("Ciphertext: "+ct);System.out.println("Decrypted: "+dt);}}
